class Solution:
    def subsets(self, nums: List[int]) -> List[List[int]]:
        res, path = [], []

        def dfs(start):
            res.append(path[:])             # 每个节点都是一个子集
            for i in range(start, len(nums)):
                path.append(nums[i])
                dfs(i + 1)                  # 下一个只能从后面选
                path.pop()

        dfs(0)
        return res

class Solution:
    def subsets(self, nums: List[int]) -> List[List[int]]:
        res = [[]]
        for x in nums:
            res += [s + [x] for s in res]
        return res

